import {ScrollViewStyleReset, useServerDocumentContext} from 'expo-router/html';
import type {PropsWithChildren} from 'react';

const SITE = 'https://smartlife-budget.web.app';
const NAME = 'SmartLife & Budget Balance';
const DESCRIPTION = 'จัดการชีวิตและการเงินในที่เดียว: ตารางเรียน งาน โน้ต และงบประมาณ พร้อมผู้ช่วย AI';

/**
 * The web root HTML: Expo Router's own default document, unchanged, plus the
 * brand's icons (generated by scripts/generate-brand-assets.cjs), the web
 * manifest and the link-preview image. The favicon itself is set per page
 * with each screen's title. This only runs at build time, in Node.
 */
export default function Root({children}: PropsWithChildren) {
  const {bodyAttributes, bodyNodes, htmlAttributes, headNodes} = useServerDocumentContext();
  return (
    <html lang="en" {...htmlAttributes}>
      <head>
        <meta charSet="utf-8" />
        <meta httpEquiv="X-UA-Compatible" content="IE=edge" />
        <meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no" />
        <ScrollViewStyleReset />
        <link href="/icon-favicon-32.png" rel="icon" sizes="32x32" type="image/png" />
        <link href="/icon-favicon-16.png" rel="icon" sizes="16x16" type="image/png" />
        <link href="/icon-apple-touch-180.png" rel="apple-touch-icon" sizes="180x180" />
        <link href="/manifest.webmanifest" rel="manifest" />
        <meta content={NAME} property="og:title" />
        <meta content={DESCRIPTION} property="og:description" />
        <meta content="website" property="og:type" />
        <meta content={SITE} property="og:url" />
        <meta content={`${SITE}/brand-social-1200x630.png`} property="og:image" />
        <meta content="1200" property="og:image:width" />
        <meta content="630" property="og:image:height" />
        <meta content="SmartLife" property="og:image:alt" />
        <meta content="summary_large_image" name="twitter:card" />
        <meta content={`${SITE}/brand-social-1200x630.png`} name="twitter:image" />
        {headNodes}
      </head>
      <body {...bodyAttributes}>
        {children}
        {bodyNodes}
      </body>
    </html>
  );
}
